[ExtensionOf(FormDatasourceStr(RetailInstanceAttributeValues, EcoResAttribute))]
public final class RetailInstanceAttributeValueFormGUP_Extension
{
    private boolean globalUnifiedPricingEnabled = FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance());

}

Method.Source:
public void init()
{
    next init();

    Common commonTable = element.args().record();

    if (globalUnifiedPricingEnabled
        && commonTable.TableId == tableNum(SalesTable))
    {
        this.initSalesOrderPricingAttributes(commonTable);
    }

    if (globalUnifiedPricingEnabled
        && commonTable.TableId == tableNum(GUPPricingTree))
    {
        this.initPricingTreePricingAttributes(commonTable);
    }

    if (globalUnifiedPricingEnabled
        && commonTable.TableId == tableNum(RetailPricingSimulatorSalesTransaction))
    {
        this.initPricingSimulatorPricingAttributes(commonTable);
    }
}

/// <summary>
/// Instantiates attributes on a sales order.
/// </summary>
/// <param name = "_salesTable">The row of the sales table.</param>
private void initSalesOrderPricingAttributes(SalesTable _salesTable)
{
    GUPParameters gupParameters;
    Set attributeGroupRecIdSet = new Set(Types::Int64);

    select firstonly SalesOrderAttributeGroup from gupParameters
            where gupParameters.DataAreaId == _salesTable.DataAreaId;

    attributeGroupRecIdSet.add(gupParameters.SalesOrderAttributeGroup);

    // Get the sales table instance value
    RetailSalesTableInstanceValue retailSalesTableInstanceValue = RetailSalesTableInstanceValue::findOrCreate(_salesTable.SalesId, _salesTable.DataAreaId);

    this.initAttributeValues(attributeGroupRecIdSet, retailSalesTableInstanceValue.RecId);
}

/// <summary>
/// Instantiates attributes on a price tree.
/// </summary>
/// <param name = "_priceTree">The row of the price tree.</param>
private void initPricingTreePricingAttributes(GUPPricingTree _priceTree)
{
    GUPParameters gupParameters;
    Set attributeGroupRecIdSet = new Set(Types::Int64);

    select firstonly SalesOrderAttributeGroup from gupParameters
            where gupParameters.DataAreaId == _priceTree.DataAreaId;

    attributeGroupRecIdSet.add(gupParameters.SalesOrderAttributeGroup);

    // Get the price tree instance value
    GUPPriceTreeInstanceValue gupPriceTreeInstanceValue = GUPPriceTreeInstanceValue::findOrCreate(_priceTree.Name, _priceTree.DataAreaId);

    this.initAttributeValues(attributeGroupRecIdSet, gupPriceTreeInstanceValue.RecId);
}

/// <summary>
/// Instantiates attributes on a pricing simulator.
/// </summary>
/// <param name = "_retailPricingSimulatorSalesTransaction">The row of the pricing simulator.</param>
private void initPricingSimulatorPricingAttributes(RetailPricingSimulatorSalesTransaction _retailPricingSimulatorSalesTransaction)
{
    GUPParameters gupParameters;
    Set attributeGroupRecIdSet = new Set(Types::Int64);

    select firstonly SalesOrderAttributeGroup from gupParameters
            where gupParameters.DataAreaId == _retailPricingSimulatorSalesTransaction.DataAreaId;

    attributeGroupRecIdSet.add(gupParameters.SalesOrderAttributeGroup);

    // Get the pricing simulator instance value
    GUPPricingSimulatorInstanceValue gupPricingSimulatorInstanceValue = GUPPricingSimulatorInstanceValue::findOrCreate(_retailPricingSimulatorSalesTransaction.SimulationName, _retailPricingSimulatorSalesTransaction.DataAreaId);

    this.initAttributeValues(attributeGroupRecIdSet, gupPricingSimulatorInstanceValue.RecId);
}
